CREATE TABLE public.pedidos (numero_pedido text PRIMARY KEY, data_pedido text NOT NULL DEFAULT '', nome_loja text NOT NULL DEFAULT '', transportadora text NOT NULL DEFAULT '', origem text NOT NULL DEFAULT '', marca text NOT NULL DEFAULT '', uf_destino text NOT NULL DEFAULT '', escala_coleta text NOT NULL DEFAULT '', status_coleta text NOT NULL DEFAULT 'Pendente', status_contato text NOT NULL DEFAULT '', situacao text NOT NULL DEFAULT 'AGUARDANDO', coletado_at timestamptz, data_coleta timestamptz, importado_at timestamptz, situacao_updated_at timestamptz, data_alteracao_situacao timestamptz, importado_por text NOT NULL DEFAULT '', editado_por text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.pedidos TO authenticated;
GRANT ALL ON public.pedidos TO service_role;
ALTER TABLE public.pedidos ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.historico_alteracoes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), numero_pedido text NOT NULL, usuario text NOT NULL DEFAULT '', campo text NOT NULL, valor_anterior text NOT NULL DEFAULT '', valor_novo text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.historico_alteracoes TO authenticated;
GRANT ALL ON public.historico_alteracoes TO service_role;
ALTER TABLE public.historico_alteracoes ENABLE ROW LEVEL SECURITY;
CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=(select auth.uid()));
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role); $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.is_collection_operator() RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT (select auth.uid()) IS NOT NULL AND lower((select auth.jwt())->>'email') ~ '^[^@]+@(somagrupo\.com\.br|usereserva\.com)$'; $$;
REVOKE ALL ON FUNCTION public.is_collection_operator() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_collection_operator() TO authenticated,service_role;
CREATE POLICY operators_read ON public.pedidos FOR SELECT TO authenticated USING ((select public.is_collection_operator()));
CREATE POLICY operators_insert ON public.pedidos FOR INSERT TO authenticated WITH CHECK ((select public.is_collection_operator()));
CREATE POLICY operators_update ON public.pedidos FOR UPDATE TO authenticated USING ((select public.is_collection_operator())) WITH CHECK ((select public.is_collection_operator()));
CREATE POLICY operators_delete_expired_or_admin ON public.pedidos FOR DELETE TO authenticated USING ((select public.is_collection_operator()) AND (public.has_role((select auth.uid()),'admin') OR (status_coleta='Coletado' AND coletado_at IS NOT NULL AND (SELECT count(*) FROM generate_series(date_trunc('day',coletado_at)+interval '1 day',date_trunc('day',now()),interval '1 day') d WHERE extract(isodow from d)<6)>=2)));
CREATE POLICY operators_history_read ON public.historico_alteracoes FOR SELECT TO authenticated USING ((select public.is_collection_operator()));
CREATE POLICY operators_history_insert ON public.historico_alteracoes FOR INSERT TO authenticated WITH CHECK ((select public.is_collection_operator()));
CREATE FUNCTION public.assign_collection_admin() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.email_confirmed_at IS NOT NULL AND lower(NEW.email) IN ('fellipe.bacelar@usereserva.com','transporteb2c@somagrupo.com.br','renan.ribeiro@somagrupo.com.br') THEN INSERT INTO public.user_roles(user_id,role) VALUES (NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
CREATE TRIGGER collection_admin_on_verified AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_collection_admin();
CREATE FUNCTION public.email_existe(_email text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM auth.users WHERE lower(email)=lower(_email)); $$;
REVOKE ALL ON FUNCTION public.email_existe(text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.email_existe(text) TO service_role;
CREATE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END; $$;
CREATE TRIGGER pedidos_set_updated_at BEFORE UPDATE ON public.pedidos FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE INDEX idx_pedidos_created_numero ON public.pedidos(created_at,numero_pedido);
CREATE INDEX idx_pedidos_status_coleta ON public.pedidos(status_coleta);
CREATE INDEX idx_historico_created_at ON public.historico_alteracoes(created_at DESC);
CREATE FUNCTION public.importar_pedidos_bulk(p_pedidos jsonb) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE v_count integer; BEGIN INSERT INTO public.pedidos AS p (numero_pedido,data_pedido,nome_loja,transportadora,origem,marca,uf_destino,escala_coleta,status_coleta,status_contato,situacao,situacao_updated_at,coletado_at,data_coleta,importado_at,updated_at,importado_por) SELECT x.numero_pedido,COALESCE(x.data_pedido,''),COALESCE(x.nome_loja,''),COALESCE(x.transportadora,''),COALESCE(x.origem,''),COALESCE(x.marca,''),COALESCE(x.uf_destino,''),COALESCE(x.escala_coleta,''),COALESCE(x.status_coleta,'Pendente'),COALESCE(x.status_contato,''),COALESCE(x.situacao,'AGUARDANDO'),x.situacao_updated_at,x.coletado_at,x.data_coleta,COALESCE(x.importado_at,now()),COALESCE(x.updated_at,now()),COALESCE(x.importado_por,'') FROM jsonb_to_recordset(p_pedidos) AS x(numero_pedido text,data_pedido text,nome_loja text,transportadora text,origem text,marca text,uf_destino text,escala_coleta text,status_coleta text,status_contato text,situacao text,situacao_updated_at timestamptz,coletado_at timestamptz,data_coleta timestamptz,importado_at timestamptz,updated_at timestamptz,importado_por text) WHERE x.numero_pedido IS NOT NULL AND x.numero_pedido<>'' ON CONFLICT(numero_pedido) DO UPDATE SET data_pedido=EXCLUDED.data_pedido,nome_loja=EXCLUDED.nome_loja,transportadora=EXCLUDED.transportadora,origem=EXCLUDED.origem,marca=EXCLUDED.marca,uf_destino=EXCLUDED.uf_destino,escala_coleta=EXCLUDED.escala_coleta,status_coleta=EXCLUDED.status_coleta,coletado_at=EXCLUDED.coletado_at,data_coleta=EXCLUDED.data_coleta,importado_at=EXCLUDED.importado_at,updated_at=EXCLUDED.updated_at,importado_por=CASE WHEN p.importado_por='' THEN EXCLUDED.importado_por ELSE p.importado_por END; GET DIAGNOSTICS v_count=ROW_COUNT; RETURN v_count; END; $$;
CREATE FUNCTION public.marcar_coletados_bulk(p_numeros text[],p_coletado_at timestamptz) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE v_count integer; BEGIN UPDATE public.pedidos SET status_coleta='Coletado',coletado_at=p_coletado_at,data_coleta=p_coletado_at WHERE numero_pedido=ANY(p_numeros); GET DIAGNOSTICS v_count=ROW_COUNT; RETURN v_count; END; $$;
CREATE FUNCTION public.marcar_coletados_por_timestamp(p_antes_de timestamptz,p_coletado_at timestamptz) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE v_count integer; BEGIN UPDATE public.pedidos SET status_coleta='Coletado',coletado_at=p_coletado_at,data_coleta=p_coletado_at,updated_at=p_coletado_at WHERE status_coleta='Pendente' AND importado_at<p_antes_de; GET DIAGNOSTICS v_count=ROW_COUNT; RETURN v_count; END; $$;
CREATE FUNCTION public.registrar_historico_bulk(p_eventos jsonb) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE v_count integer; BEGIN INSERT INTO public.historico_alteracoes(numero_pedido,usuario,campo,valor_anterior,valor_novo) SELECT x.numero_pedido,COALESCE(x.usuario,''),x.campo,COALESCE(x.valor_anterior,''),COALESCE(x.valor_novo,'') FROM jsonb_to_recordset(p_eventos) AS x(numero_pedido text,usuario text,campo text,valor_anterior text,valor_novo text); GET DIAGNOSTICS v_count=ROW_COUNT; RETURN v_count; END; $$;
REVOKE ALL ON FUNCTION public.importar_pedidos_bulk(jsonb),public.marcar_coletados_bulk(text[],timestamptz),public.marcar_coletados_por_timestamp(timestamptz,timestamptz),public.registrar_historico_bulk(jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.importar_pedidos_bulk(jsonb),public.marcar_coletados_bulk(text[],timestamptz),public.marcar_coletados_por_timestamp(timestamptz,timestamptz),public.registrar_historico_bulk(jsonb) TO authenticated,service_role;